import{auth}from"./firebase.js";import{forgeXModal}from"./utils.js";import{sendPasswordResetEmail}from"https://www.gstatic.com/firebasejs/10.7.1/firebase-auth.js";const resetForm=document.querySelector("form"),emailInput=document.getElementById("email"),resetButton=document.querySelector(".login-btn");resetForm&&emailInput&&resetButton&&resetForm.addEventListener("submit",async e=>{e.preventDefault(),resetButton.disabled=!0,resetButton.innerText="Folyamatban...";try{await sendPasswordResetEmail(auth,emailInput.value.trim()),await forgeXModal("Link elkuldve","Elküldtük a jelszó-visszaállító linket az e-mail címedre.")}catch(e){console.error("Password reset error:",e.code),await forgeXModal("Hiba történt","A jelszó-visszaállítás most nem sikerült. Ellenőrizd az e-mail címet, majd próbáld újra.")}finally{resetButton.disabled=!1,resetButton.innerText="Jelszó visszaállítása"}});